print("Aufgabe 1: Zahl 32 in Python darstellen")
print(32)
print()  # Leerzeile zur besseren Übersicht


print("Aufgabe 2: Datentyp von 14 feststellen")
print(type(14))
# Erklärung:
# 14 ist eine ganze Zahl.
# Der Datentyp heißt in Python: int
print()


print("Aufgabe 3: Datentyp von 14.0 feststellen")
print(type(14.0))
# Erklärung:
# 14.0 hat eine Nachkommastelle.
# Auch wenn es mathematisch wie 14 aussieht, ist es in Python eine Kommazahl.
# Der Datentyp heißt: float
print()


print('Aufgabe 4: Datentyp von "14" feststellen')
print(type("14"))
# Erklärung:
# "14" steht in Anführungszeichen.
# Dadurch ist es keine Zahl, sondern Text.
# Der Datentyp heißt: str
print()


print("Aufgabe 5: Wert von 1 + 2 * 3 berechnen")
print(1 + 2 * 3)
# Erklärung:
# Python rechnet wie in der Mathematik:
# Punktrechnung vor Strichrechnung.
#
# Also zuerst:
# 2 * 3 = 6
#
# Danach:
# 1 + 6 = 7
#
# Ergebnis: 7
print()


# Kurze Merkhilfe:
# int   = ganze Zahl, zum Beispiel 14
# float = Kommazahl, zum Beispiel 14.0
# str   = Text/String, zum Beispiel "14"
